import {preferredToolURL} from './network.mjs';
import {tools,categories,icon,guideCount} from './catalog-client.mjs';
import {escapeHTML as e} from './core.mjs';
export const href=(type,id)=>type==='home'?'./':type==='tool'?(preferredToolURL(id)||`./tools/${id}/`):type==='category'?`./categories/${id}/`:type==='article'?`./blog/${id}/`:type==='blogCategory'?`./blog/category/${id}/`:type==='catalog'?'./tools/':`./${type}/`;
const newIds=new Set(tools.slice(42).map(t=>t.id));
const groups=[['Create','palette',['images','creators','audio']],['Build','code',['developer','web','security','pdf']],['Work','receipt',['business','calculators','text','money']],['Life','book',['study','education','health','sports']]];
const grouped=new Set(groups.flatMap(g=>g[2]));
export function navHTML(active='all',count=0){const link=c=>`<a class="nav-link ${active===c.id?'active':''}" href="${href('category',c.id)}" ${active===c.id?'aria-current="page"':''}><span>${e(c.name)}</span><span class="nav-chevron" aria-hidden="true">›</span></a>`;return `<a class="sidebar-count ${active==='all'?'selected':''}" href="./tools/"><strong>${tools.length}</strong> free tools <span>View all ${icon('arrow')}</span></a>`+groups.map(([name,symbol,ids])=>`<details class="category-group" open><summary>${icon(symbol)}<span>${name}</span><span class="group-chevron" aria-hidden="true">⌃</span></summary><div>${ids.map(id=>link(categories.find(c=>c.id===id))).join('')}</div></details>`).join('')+`<details class="category-group nav-more" ${categories.some(c=>c.id===active&&!grouped.has(c.id)&&c.id!=='all')?'open':''}><summary>${icon('grid')}<span>More topics</span><span class="group-chevron" aria-hidden="true">⌃</span></summary><div>${categories.filter(c=>c.id!=='all'&&!grouped.has(c.id)).map(link).join('')}</div></details><div class="sidebar-utility"><a class="nav-link" href="./sites/">${icon('globe')} Nepocore websites</a><a class="nav-link ${active==='guides'?'active':''}" href="./blog/" ${active==='guides'?'aria-current="page"':''}>${icon('book')} Practical guides <span class="count">${guideCount}</span></a><a class="nav-link ${active==='favorites'?'active':''}" href="${href('favorites')}" ${active==='favorites'?'aria-current="page"':''}>${icon('star')} Bookmarks <span class="count">${count}</span></a></div>`;}
export const starHTML=(t,favorites=new Set())=>`<button class="star-btn ${favorites.has(t.id)?'saved':''}" data-star="${t.id}" aria-label="${favorites.has(t.id)?'Remove':'Add'} ${e(t.title)} ${favorites.has(t.id)?'from':'to'} favorites" aria-pressed="${favorites.has(t.id)}">${icon('star')}</button>`;
export const cardHTML=(t,favorites=new Set())=>`<article class="tool-card cat-${t.category}">${starHTML(t,favorites)}<a href="${href('tool',t.id)}"><img class="tool-preview" src="./assets/tool-previews/${t.id}.svg" width="640" height="240" alt="" loading="lazy" decoding="async"><div class="tool-card-copy"><h3>${e(t.title)}</h3><p>${e(t.description)}</p><div class="tool-card-meta"><span>${e(categories.find(c=>c.id===t.category)?.name||'Tool')}</span><b>Free</b><span class="open-tool">Open tool ${icon('arrow')}</span></div></div></a></article>`;
const normalizeSearch=value=>value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\bjpg\b/g,'jpeg').replace(/\bphotos?\b/g,'image').replace(/\bcalculators?\b/g,'calculator').replace(/[^\p{L}\p{N}]+/gu,' ').trim();
const searchAliases={'image-compressor':'compress shrink photo 50 100 200 kb file size jpeg webp', 'pdf-compressor':'reduce shrink compress pdf local scan', 'resume-builder':'resume cv curriculum vitae pdf no signup', 'age':'date birth birthday years months days deadline','image-converter':'convert jpeg png webp format jpg', 'background-remover':'erase cutout transparent remove background', 'image-cropper':'crop image cut resize', 'ielts-overall':'ielts overall band score', 'image-to-text':'ocr scan extract text', 'qr-code':'qr code maker generator cool custom styled wifi link', 'pdf-merge':'combine merge pdf', 'pdf-extract':'split extract pdf pages'};
const searchIndex=new Map(tools.map(t=>[t.id,{text:normalizeSearch(`${t.title} ${t.description} ${t.category} ${t.id} ${t.aliases||''} ${searchAliases[t.id]||''}`),title:normalizeSearch(t.title)}]));
export function filteredTools(category='all',query='',favorites=new Set()){
 const tokens=normalizeSearch(query).split(' ').filter(x=>x&&!['to','from','a','an','and','the','for','of','tool','tools'].includes(x));
 return tools.filter(t=>(category==='favorites'?favorites.has(t.id):category==='all'||t.category===category)&&tokens.every(token=>searchIndex.get(t.id).text.includes(token))).sort((a,b)=>{if(!tokens.length)return 0;const score=t=>(t.id==='image-converter'&&tokens.includes('png')&&tokens.includes('jpeg')?10:0)+tokens.reduce((s,x)=>s+(searchIndex.get(t.id).title.includes(x)?2:0)+(searchIndex.get(t.id).title.startsWith(x)?1:0),0);return score(b)-score(a);});
}
